    if (typeof apiUrl !== 'string' || !urlPattern.test(apiUrl)) {
        return null;
    }

    // Validate userId
    if (typeof userId !== 'string' || userId.trim() === '') {
        return null;
    }

    // Construct and return the full URL
    return `${apiUrl}/${encodeURIComponent(userId)}`;
}
